mapper.select:
SELECT  FROM organizations o
WHERE (o.name ILIKE '%' || #{params.Query} || '%' OR o.uuid::text = #{params.Query})
AND o.uuid > #{params.After}
ORDER BY o.uuid LIMIT #{params.Limit}

SELECT uuid, email, name, role FROM users WHERE organization_uuid = #{params.OrganizationUUID} AND deleted_at IS NULL
AND uuid > #{params.After}
ORDER BY uuid LIMIT #{params.Limit}

SELECT uuid, external_id, name, is_default, archived_at IS NOT NULL AS archived FROM workspaces
WHERE organization_uuid = #{params.OrganizationUUID}
AND uuid > #{params.After}
ORDER BY uuid LIMIT #{params.Limit}
